import {escapeHtml as esc} from './components.js';
export const hubExamples=['하이일드 스프레드는 어때?','VIX와 실질금리 비교해줘','미국 경제 전반은 어때?','인플레는 둔화되는데 금리는 왜 높아?','경기 침체 신호가 있어?','주택시장은 약해지고 있어?','금융시장의 자금 조달 여건은 어때?','소비가 줄어드는 중이야?'];
export const hubLabels={economy:'경기·성장',inflation:'물가',employment:'고용',consumption:'소비·소득',rates:'금리·채권',housing:'주택',manufacturing:'기업·제조업',credit:'신용·금융여건',liquidity:'유동성',trade:'무역·달러',energy:'에너지·원자재',fiscal:'재정'};
const sectors={Industrials:'산업재','Consumer Cyclical':'경기소비재','Consumer Defensive':'필수소비재',Financial:'금융','Real Estate':'부동산',Technology:'기술',Energy:'에너지','Basic Materials':'소재'};
export function hubFields(data,card){return data.hub.fields.map(f=>{const core=data.core.filter(s=>s.field===f.id),related=data.related.filter(s=>s.field===f.id);return `<section class="macro-field" data-macro-field="${esc(f.id)}"><header class="macro-section-title"><div><h2>${esc(f.name)}</h2></div><span>${core.length}개 지표</span></header><div class="macro-core">${core.map(card).join('')||'<div class="surface macro-empty">확인 가능한 지표가 없어 분석을 보류합니다.</div>'}</div><details class="surface macro-related"><summary>${esc(f.name)} 관련 지표 더 보기 <span>${related.length}개</span></summary><div class="macro-core">${related.map(card).join('')||'<p>추가 지표가 없습니다.</p>'}</div></details><div class="macro-sector-links"><span>관련 섹터 성과</span>${f.sectors.map(sector=>`<a href="/?market=US&sector=${encodeURIComponent(sector)}" data-nav>${esc(sectors[sector]||sector)} →</a>`).join('')}<small>섹터맵의 별도 시세 기준일을 확인하세요. 경제지표가 주가 변동의 원인이라는 뜻은 아닙니다.</small></div></section>`;}).join('');}
export function hubMenu(){return `<section class="surface macro-browse"><h2>분야별 지표</h2><nav aria-label="매크로 분야">${Object.entries(hubLabels).map(([id,name])=>`<button data-macro-topic="${id}" aria-pressed="false">${name}</button>`).join('')}</nav></section>`;}
export const hubLegal='<footer class="macro-legal"><p>This product uses the FRED® API but is not endorsed or certified by the Federal Reserve Bank of St. Louis.</p><a href="https://fred.stlouisfed.org/legal/" target="_blank" rel="noopener noreferrer">출처·이용 조건</a><span>한국 질문에는 연결된 한국 자료만 사용합니다.</span></footer>';
